fc:[
["Quali sono i gliomi di alto grado?","Astrocitoma anaplastico e glioblastoma multiforme: molto replicativi e infiltranti."],
["Sopravvivenza mediana del glioblastoma?","12-18 mesi."],
["Fattori prognostici favorevoli nei gliomi?","MGMT ipermetilato, codelezione 1p/19q, chirurgia radicale, giovane età, buon performance status."],
["Pazienti fit e frail con glioblastoma?","Fit 60-70%; frail (oltre 65 anni o basso PS) 30-35%."],
["Quanto allunga la vita la radioterapia nel GBM?","Da 6 a 10-12 mesi; nell’anaplastico da 12-14 a 36 mesi."],
["Come agisce la temozolomide?","Alchilante orale lipofilo che passa la barriera ematoencefalica."],
["Quale RM si usa per pianificare un glioma?","T1 con contrasto e FLAIR: cercine captante, core necrotico, edema."],
["Come si definiscono GTV e CTV nel glioblastoma?","GTV: lesione captante + cavità. CTV: GTV + 2 cm + edema (80% delle recidive)."],
["Come si divide la dose nei pazienti fit?","46 Gy su tutto il CTV, poi 14 Gy sul letto + 2 cm."],
["Perché non superare i 60 Gy nel GBM?","Per il rischio di radionecrosi."],
["Limite di dose per tronco, chiasma e nervi ottici?","Circa 54 Gy."],
["Tossicità iniziale dell’irradiazione cerebrale?","Aumento dell’edema con cefalea, nausea e vomito; si previene con betametasone."],
["Perché nel GBM lo standard è la 3D-CRT?","Volumi ampi e prognosi severa rendono poco utili tecniche più sofisticate."],
["Boost stereotassico e GliaSite nel GBM?","Boost fino a 66-70 Gy non standard (radionecrosi); GliaSite abbandonata."],
["Sopravvivenze mediane dei gliomi di basso grado?","Astrocitoma 4,7 anni, oligoastrocitoma 7,1, oligodendroglioma 9,8."],
["Terapia principale dei gliomi di basso grado?","Chirurgia il più radicale possibile; chemio senza indicazione standard."],
["Rischi della radioterapia nei gliomi di basso grado?","Deficit cognitivi, di attenzione e di memoria nei giovani lungo-sopravviventi."],
["Come evolvono i gliomi di basso grado alla recidiva?","Possono trasformarsi in alto grado: vanno seguiti con imaging."],
["Origine delle metastasi cerebrali?","Mammella, polmone, colon-retto, melanoma; più spesso sovratentoriali."],
["Effetti dell’irradiazione delle metastasi cerebrali?","Sintomi migliorati nel 70-90%; sopravvivenza 6-8 mesi contro 3-4."],
["Dove si trova il neurinoma dell’acustico?","Nell’angolo ponto-cerebellare."],
["Perché la stereotassi è adatta ai tumori benigni encefalici?","Crea isodosi concentriche con ripida caduta di dose."]
],
